import{z as l,x as c,o as s,c as p,q as i,j as t,D as o,d as a,s as r,S as E,b as d}from"./chunks/framework.C8m1ZpeB.js";const _=JSON.parse('{"title":"设备节点","description":"","frontmatter":{"title":"设备节点","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/device-nodes.md","filePath":"cs/device-nodes.md","lastUpdated":1791063341000}'),B={name:"cs/device-nodes.md"};function A(m,e,f,u,h,v){const n=c("Mermaid");return s(),p("div",null,[e[2]||(e[2]=i('<h1 id="设备节点" tabindex="-1">设备节点 <a class="header-anchor" href="#设备节点" aria-label="Permalink to &quot;设备节点&quot;">​</a></h1><div class="epigraph"><p>设备节点是带主次设备号的 inode：打开它不读数据块，而是把后续 I/O 送到对应驱动。</p><footer>—— 据 Thompson, UNIX Implementation；Bach；Linux devices.txt 对主次号的整理</footer></div><p><a href="/cs/tmpfs">上一课</a>的文件仍是页。Unix「一切皆文件」还包括磁盘、终端、随机数：<a href="/cs/inode-dir">inode</a> 类型为字符或块设备，内容是 <strong>dev_t</strong>。缺口是设备节点与 <a href="/cs/vfs">VFS</a> 如何接到驱动，而不是存储栈的调度器。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>若用户必须 <code>ioctl</code> 一个隐藏句柄才能访问磁盘，POSIX 工具链裂开。设备节点：<code>mknod</code> 在某文件系统（常为 devtmpfs）上造 inode，<code>open</code> 走 <code>chrdev_open</code>/<code>blkdev_open</code>，fops 来自驱动。块设备还可再被挂载成 FS——同一盘既有 <code>/dev/sda</code> 又有 <code>/</code>。缺口：主次号分配、<code>uevent</code> 与后课 udev、以及权限（谁能打开裸盘）。</p><p><span class="marginnote">字符设备按字节流；块设备按块，可走页缓存（缓冲 I/O）。裸盘 <code>O_DIRECT</code> 是后课。本课不把 NVMe 多队列写完。</span></p><p><span class="marginnote">数字实例：<code>ls -l /dev/sda</code> 输出里的「8, 0」就是主、次设备号。Linux 里主号 8 固定分给 sd（SCSI/SATA 磁盘）驱动，次号 0 是整盘、15 是第 16 个分区。主次号不是随便编的，内核靠这对数字查表找到驱动。</span></p><p><span class="marginnote">直觉类比：主次号像公司电话总机——主号决定转接哪个部门（哪个驱动），次号是部门里的分机号（该驱动管的第几个设备实例）。同一芯片上的两个串口，往往主号相同、次号不同。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p><code>read(/dev/zero)</code>：驱动填零，不经块分配器。<code>read(/dev/sda)</code>：块层按偏移读扇区，可进页缓存（bdev inode）。<code>ioctl</code> 传送设备特定命令。对照普通文件：没有 extent，偏移是设备地址。对照 <a href="/cs/fuse">FUSE</a>：用户态也可以实现字符设备，但经典路径是内核 cdev。</p>',10)),(s(),t(E,null,{default:o(()=>[r(n,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20PATH%5B%22%2Fdev%2Fsda%22%5D%20--%3E%20INO%5B%22%E8%AE%BE%E5%A4%87%20inode%22%5D%0A%20%20INO%20--%3E%20MAJ%5B%22%E4%B8%BB%E6%AC%A1%E8%AE%BE%E5%A4%87%E5%8F%B7%22%5D%0A%20%20MAJ%20--%3E%20DRV%5B%22%E9%A9%B1%E5%8A%A8%20fops%22%5D%0A%20%20DRV%20--%3E%20BLK%5B%22%E5%9D%97%E5%B1%82%E6%88%96%E5%AD%97%E7%AC%A6%E8%B7%AF%E5%BE%84%22%5D%0A"})]),fallback:o(()=>[...e[0]||(e[0]=[a(" Loading... ",-1)])]),_:1})),e[3]||(e[3]=d("h2",{id:"机制",tabindex:"-1"},[a("机制 "),d("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),e[4]||(e[4]=d("p",null,[a("设备节点把驱动登记进文件系统名空间，使权限、打开计数、poll 与普通文件共用 VFS。这是 Unix 的关键接头：备份、dd、加密卷都从打开一个节点开始。不要把本课写成硬件总线枚举全文——"),d("a",{href:"/cs/device-model-binding"},"设备模型"),a(" 在启动课序。")],-1)),e[5]||(e[5]=d("p",null,[a("两张图回答的问题不同：上面那张画「打开节点怎么找到驱动」，这张画「数据本身从哪来」——读 "),d("code",null,"/dev/zero"),a(" 时数据是驱动现场造的，读 "),d("code",null,"/dev/sda"),a(" 时数据要经块层、还可能先在页缓存里。")],-1)),(s(),t(E,null,{default:o(()=>[r(n,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20TD%0A%20%20Z%5B%22read(%2Fdev%2Fzero)%22%5D%20--%3E%20CZ%5B%22%E5%AD%97%E7%AC%A6%E9%A9%B1%E5%8A%A8%20zero%22%5D%0A%20%20CZ%20--%3E%20F1%5B%22%E9%A9%B1%E5%8A%A8%E7%9B%B4%E6%8E%A5%E6%8A%8A%E9%9B%B6%E5%A1%AB%E8%BF%9B%E7%94%A8%E6%88%B7%E7%BC%93%E5%86%B2%22%5D%0A%20%20S%5B%22read(%2Fdev%2Fsda)%22%5D%20--%3E%20BL%5B%22%E5%9D%97%E5%B1%82%E6%8C%89%E5%81%8F%E7%A7%BB%E6%8D%A2%E7%AE%97%E6%89%87%E5%8C%BA%22%5D%0A%20%20BL%20--%3E%20PC%7B%22%E9%A1%B5%E7%BC%93%E5%AD%98%E9%87%8C%E5%B7%B2%E6%9C%89%E8%BF%99%E5%9D%97%E5%90%97%22%7D%0A%20%20PC%20--%20%22%E5%91%BD%E4%B8%AD%22%20--%3E%20U%5B%22%E4%BB%8E%E9%A1%B5%E7%BC%93%E5%AD%98%E6%8B%B7%E7%BB%99%E7%94%A8%E6%88%B7%22%5D%0A%20%20PC%20--%20%22%E6%9C%AA%E5%91%BD%E4%B8%AD%22%20--%3E%20DISK%5B%22%E5%90%91%E7%A3%81%E7%9B%98%E5%8F%91%E8%AF%BB%E8%AF%B7%E6%B1%82%22%5D%0A%20%20DISK%20--%3E%20PC%0A"})]),fallback:o(()=>[...e[1]||(e[1]=[a(" Loading... ",-1)])]),_:1})),e[6]||(e[6]=i('<p><span class="marginnote">常见误区：初学者容易以为 <code>rm /dev/sda</code> 会把磁盘驱动从内核里拆掉。实际上删掉的只是文件系统里一个 inode，驱动仍登记在内核中，devtmpfs 下次还会把节点重新造出来——删的是「门牌」，不是「房子」。</span></p><p>与 <a href="/cs/rename-atomicity">rename</a>：设备节点可改名，主次号不变；删除节点不卸载驱动。</p><p>实现上：devtmpfs 在内核里造节点，udev 再改名。容器里 mknod 常被 cap 与设备 cgroup 拦住，不是 VFS 不懂设备。块设备的 bdev inode 有自己的页缓存，和文件系统页缓存是两套。 读法上只引用<a href="/cs/tmpfs">上一课</a>的结论，不把对象换成训练推理或限价簿。</p><p>本课在操作系统进阶的「文件系统实现 / 接口进阶」课序里，对象是 <strong>设备节点</strong>。</p><ul><li>先修只引用，不重导：上一课的结论当公理，本课只补差。</li><li>五栏不吞并：不把本课写成大模型训练/推理，也不写成限价簿或权重量化。</li><li>文献用 OSTEP、McKusick、内核文档与具名会议论文；不发明 arXiv 编号。</li></ul><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入 namespace 里的设备可见性全部规则。不保证容器里 mknod 被 cap 拦住的每条路径——capabilities 后课。下一课从「打开了文件/设备」走到读路径优化：预读。</p><p>版本字段会变，课序钉的是机制对象「设备节点」，不是某一主线内核的结构体名。 后课默认：设备是带主次号的 inode。顺序读如何提前拉块进页缓存，下一课预读。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>设备节点把主次号接到驱动 fops。</li><li>块设备可再被挂载；字符设备是字节接口。</li><li>预读是下一课。</li><li>出处：Thompson；Bach；Linux device 文档；Tanenbaum <em>MOS</em>。</li></ul>',10))])}const C=l(B,[["render",A]]);export{_ as __pageData,C as default};
